alter table public.mountain_foundation_profiles
  drop constraint if exists mountain_foundation_profiles_region_check;

alter table public.mountain_foundation_profiles
  drop constraint if exists mountain_foundation_profiles_primary_region_check;

alter table public.mountain_foundation_profiles
  add constraint mountain_foundation_profiles_region_check
  check (region in ('HOKKAIDO', 'TOHOKU', 'HOKUSHINETSU', 'KANTO', 'HOKURIKU', 'TOKAI', 'KINKI', 'FUJI', 'OKUCHICHIBU', 'TANZAWA', 'NIKKO', 'YATSUGATAKE', 'NORTHERN_ALPS', 'CENTRAL_ALPS', 'SOUTHERN_ALPS', 'CHUGOKU', 'SHIKOKU', 'KYUSHU', 'YAKUSHIMA', 'KANTO_TOKYO', 'KANTO_TOKYO_SAITAMA_YAMANASHI', 'NORTHERN_ALPS_NAGANO', 'NORTHERN_ALPS_NAGANO_GIFU', 'JOSHU'));

alter table public.mountain_foundation_profiles
  add constraint mountain_foundation_profiles_primary_region_check
  check (primary_region in ('HOKKAIDO', 'TOHOKU', 'HOKUSHINETSU', 'KANTO', 'HOKURIKU', 'TOKAI', 'KINKI', 'FUJI', 'OKUCHICHIBU', 'TANZAWA', 'NIKKO', 'YATSUGATAKE', 'NORTHERN_ALPS', 'CENTRAL_ALPS', 'SOUTHERN_ALPS', 'CHUGOKU', 'SHIKOKU', 'KYUSHU', 'YAKUSHIMA', 'KANTO_TOKYO', 'JOSHU'));

update public.mountain_foundation_profiles
set supported_styles = array['DAY_HIKE', 'OVERNIGHT_HUT', 'OVERNIGHT_TENT', 'MULTI_DAY_TREK']::text[]
where slug = 'tsubakuro-dake';

update public.mountain_foundation_profiles
set hut_support = 'FULL_SERVICE',
    tent_site_availability = 'DESIGNATED',
    alpine_environment = 'HIGH_ALPINE_EXPOSED'
where slug = 'jonen-dake';

update public.mountain_foundation_profiles
set hut_support = 'FULL_SERVICE',
    tent_site_availability = 'DESIGNATED',
    alpine_environment = 'HIGH_ALPINE_EXPOSED'
where slug = 'cho-gatake';

update public.mountain_foundation_profiles
set snow_or_ice_risk = 'SEASONAL_PATCHES'
where slug = 'shirouma-dake';

