  helmet_guidance,
  water_availability,
  hut_support,
  tent_site_availability,
  alpine_environment,
  snow_or_ice_risk,
  route_duration_band,
  escape_options,
  cell_signal_reliability,
  bear_or_wildlife_risk,
  volcanic_risk,
  season_opening_window
)
